from taf.ul.kpi_selector.operations.sw_activation.classical_sw_activation.sw_activation_22R3 import SwActivation22R3


class SwActivation23R1(SwActivation22R3):

    def get_kpi(self, inter_release=False):  # noqa: C901
        """
        Gets kpi for software activation operation.
        :param inter_release: boolean value whether activated sw is of different stream than the one active on BTS;
                              defaults to False
        :type inter_release: bool
        :return: dictionary with timeout, requirement and operation description for software activation
        :rtype: dict
        """
        use_restrictions = True

        if all(
            (
                self.check_smod_bbmod_types(smod_type="ASIL", bbmod_types=["ABIP"]),
                self.bts.number_of_bbmods <= 1,
                self.bts.number_of_rmods <= 2,
                self.bts.number_of_nr_cells <= 2,
                self.bts.cell_technologies == "TDD",
                self.bts.setup_mode == "NSA",
                not self.bts.is_full_rack,
                not self.bts.is_multi_rat,
            )
        ):
            self.operation_details["Requirement"] = "OM_GEN_SFS_PERF_CAP.17321"
            if not self.bts.is_rmods_target_bd_sw_version_different and not inter_release:
                self.operation_details["Timeout"] += 648
            elif self.bts.is_rmods_target_bd_sw_version_different and not inter_release:
                self.operation_details["Timeout"] += 936

        elif all(
            (
                self.check_smod_bbmod_types(smod_type="ASIM", bbmod_types=["ABIP"]),
                self.bts.number_of_bbmods <= 1,
                self.bts.number_of_rmods <= 2,
                self.bts.number_of_nr_cells <= 2,
                self.bts.cell_technologies == "TDD",
                not self.bts.is_full_rack,
                not self.bts.is_multi_rat,
                self.bts.setup_mode == "NSA",
            )
        ):
            self.operation_details["Requirement"] = "OM_GEN_SFS_PERF_CAP.17322"
            if not self.bts.is_rmods_target_bd_sw_version_different and not inter_release:
                self.operation_details["Timeout"] += 468
            elif self.bts.is_rmods_target_bd_sw_version_different and not inter_release:
                self.operation_details["Timeout"] += 756

        elif all(
            (
                self.check_smod_bbmod_types(smod_type="ASIM", bbmod_types=["ABIP"]),
                self.bts.number_of_bbmods <= 1,
                self.bts.number_of_rmods <= 3,
                self.bts.number_of_nr_cells <= 3,
                self.bts.cell_technologies == "FDD",
                not self.bts.is_full_rack,
                not self.bts.is_multi_rat,
                self.bts.setup_mode == "SA",
            )
        ):
            self.operation_details["Requirement"] = "OM_GEN_SFS_PERF_CAP.17323"
            if not self.bts.is_rmods_target_bd_sw_version_different and not inter_release:
                self.operation_details["Timeout"] += 360
            elif self.bts.is_rmods_target_bd_sw_version_different and not inter_release:
                self.operation_details["Timeout"] += 648

        elif all(
            (
                self.bts.number_of_bbmods == 1,
                "ASIL" in self.bts.smod_hw_types,
                "ABIP" in self.bts.bbmod_hw_types or "ABIQ" in self.bts.bbmod_hw_types,
                self.bts.number_of_nr_cells <= 3,
                self.bts.number_of_lte_cells <= 3,
                self.bts.cell_technologies == "FDD",
                not self.bts.is_full_rack,
                self.bts.is_multi_rat,
                self.bts.radio_protocol == "CPRI",
                self.bts.setup_mode == "NSA",
            )
        ):
            self.operation_details["Requirement"] = "OM_GEN_SFS_PERF_CAP.19846"
            if not self.bts.is_rmods_target_bd_sw_version_different and not inter_release:
                self.operation_details["Timeout"] += 540
            elif self.bts.is_rmods_target_bd_sw_version_different and not inter_release:
                self.operation_details["Timeout"] += 780

        elif all(
            (
                self.bts.number_of_bbmods == 1,
                "ASIL" in self.bts.smod_hw_types,
                "ABIP" in self.bts.bbmod_hw_types or "ABIQ" in self.bts.bbmod_hw_types,
                self.bts.number_of_nr_cells <= 2,
                self.bts.number_of_lte_cells <= 2,
                self.bts.cell_technologies == "MIX",
                not self.bts.is_full_rack,
                self.bts.is_multi_rat,
            )
        ):
            self.operation_details["Requirement"] = "OM_GEN_SFS_PERF_CAP.19866"
            if not self.bts.is_rmods_target_bd_sw_version_different and not inter_release:
                self.operation_details["Timeout"] += 540
            elif self.bts.is_rmods_target_bd_sw_version_different and not inter_release:
                self.operation_details["Timeout"] += 780

        elif all(
            (
                "ASOG" in self.bts.smod_hw_types,
                self.bts.number_of_nr_cells <= 2,
                self.bts.cell_technologies == "TDD",
                not self.bts.is_full_rack,
                not self.bts.is_multi_rat,
                "AZQS" in self.bts.rmod_hw_types,
                self.bts.radio_protocol == "eCPRI",
            )
        ):
            self.operation_details["Requirement"] = "OM_GEN_SFS_PERF_CAP.26553"
            if not self.bts.is_rmods_target_bd_sw_version_different and not inter_release:
                self.operation_details["Timeout"] += 600
            elif self.bts.is_rmods_target_bd_sw_version_different and not inter_release:
                self.operation_details["Timeout"] += 720

        elif all(
            (
                "ASOH" in self.bts.smod_hw_types,
                self.bts.number_of_rmods <= 3,
                "AHEGB" in self.bts.rmod_hw_types or "AHEH" in self.bts.rmod_hw_types,
                self.bts.number_of_nr_cells <= 3,
                self.bts.cell_technologies == "FDD",
                not self.bts.is_full_rack,
                not self.bts.is_multi_rat,
                self.bts.radio_protocol == "CPRI",
            )
        ):
            self.operation_details["Requirement"] = "OM_GEN_SFS_PERF_CAP.26554"
            if not self.bts.is_rmods_target_bd_sw_version_different and not inter_release:
                self.operation_details["Timeout"] += 480
            elif self.bts.is_rmods_target_bd_sw_version_different and not inter_release:
                self.operation_details["Timeout"] += 630

        elif all(
            (
                "ASOG" in self.bts.smod_hw_types,
                self.bts.number_of_rmods <= 3,
                "AHEGB" in self.bts.rmod_hw_types or "AHEH" in self.bts.rmod_hw_types,
                0 < self.bts.number_of_lte_cells <= 3,
                self.bts.cell_technologies == "FDD",
                not self.bts.is_full_rack,
                not self.bts.is_multi_rat,
                self.bts.radio_protocol == "CPRI",
            )
        ):
            self.operation_details["Requirement"] = "OM_GEN_SFS_PERF_CAP.26556"
            if not self.bts.is_rmods_target_bd_sw_version_different and not inter_release:
                self.operation_details["Timeout"] += 480
            elif self.bts.is_rmods_target_bd_sw_version_different and not inter_release:
                self.operation_details["Timeout"] += 630

        elif all(
            (
                "ASOH" in self.bts.smod_hw_types,
                self.bts.number_of_rmods <= 4,
                "AQQL" in self.bts.rmod_hw_types,
                "AHEGB" in self.bts.rmod_hw_types or "AHEH" in self.bts.rmod_hw_types,
                self.bts.number_of_nr_cells <= 4,
                self.bts.cell_technologies == "MIX",
                not self.bts.is_full_rack,
                self.bts.radio_protocol == "MIX",
            )
        ):
            self.operation_details["Requirement"] = "OM_GEN_SFS_PERF_CAP.26557"
            if not self.bts.is_rmods_target_bd_sw_version_different and not inter_release:
                self.operation_details["Timeout"] += 600
            elif self.bts.is_rmods_target_bd_sw_version_different and not inter_release:
                self.operation_details["Timeout"] += 720

        elif all(
            (
                "ASOG" in self.bts.smod_hw_types,
                self.bts.number_of_rmods == 1,
                "FXDD" in self.bts.rmod_hw_types,
                0 < self.bts.number_of_wcdma_cells <= 6,
                not self.bts.is_full_rack,
                not self.bts.is_multi_rat,
            )
        ):
            self.operation_details["Requirement"] = "OM_GEN_SFS_PERF_CAP.28081"
            if not self.bts.is_rmods_target_bd_sw_version_different and not inter_release:
                self.operation_details["Timeout"] += 480
            elif self.bts.is_rmods_target_bd_sw_version_different and not inter_release:
                self.operation_details["Timeout"] += 630

        elif all(
            (
                "ASOG" in self.bts.smod_hw_types,
                self.bts.number_of_rmods <= 3,
                "AHEGB" in self.bts.rmod_hw_types,
                0 < self.bts.number_of_gsm_cells <= 18,
                not self.bts.is_full_rack,
                not self.bts.is_multi_rat,
                self.bts.radio_protocol == "CPRI",
            )
        ):
            self.operation_details["Requirement"] = "OM_GEN_SFS_PERF_CAP.28082"
            if not self.bts.is_rmods_target_bd_sw_version_different and not inter_release:
                self.operation_details["Timeout"] += 480
            elif self.bts.is_rmods_target_bd_sw_version_different and not inter_release:
                self.operation_details["Timeout"] += 630

        elif all(
            (
                "ASOG" in self.bts.smod_hw_types,
                self.bts.number_of_rmods <= 2,
                "AHEGB" in self.bts.rmod_hw_types,
                self.bts.number_of_gsm_cells <= 6,
                self.bts.number_of_lte_cells <= 1,
                self.bts.number_of_nr_cells <= 1,
                self.bts.number_of_wcdma_cells == 0,
                not self.bts.is_full_rack,
                self.bts.setup_mode == "NSA",
                self.bts.is_multi_rat,
                self.bts.radio_protocol == "CPRI",
                self.bts.cell_technologies == "FDD",
            )
        ):
            self.operation_details["Requirement"] = "OM_GEN_SFS_PERF_CAP.28083"
            if not self.bts.is_rmods_target_bd_sw_version_different and not inter_release:
                self.operation_details["Timeout"] += 540
            elif self.bts.is_rmods_target_bd_sw_version_different and not inter_release:
                self.operation_details["Timeout"] += 690

        elif all(
            (
                "ASOG" in self.bts.smod_hw_types,
                self.bts.number_of_rmods <= 2,
                "AHEGB" in self.bts.rmod_hw_types,
                self.bts.number_of_wcdma_cells <= 1,
                self.bts.number_of_lte_cells <= 1,
                self.bts.number_of_nr_cells <= 1,
                self.bts.number_of_gsm_cells == 0,
                not self.bts.is_full_rack,
                self.bts.setup_mode == "NSA",
                self.bts.is_multi_rat,
                self.bts.radio_protocol == "CPRI",
                self.bts.cell_technologies == "FDD",
            )
        ):
            self.operation_details["Requirement"] = "OM_GEN_SFS_PERF_CAP.28084"
            if not self.bts.is_rmods_target_bd_sw_version_different and not inter_release:
                self.operation_details["Timeout"] += 540
            elif self.bts.is_rmods_target_bd_sw_version_different and not inter_release:
                self.operation_details["Timeout"] += 690

        else:
            return super(SwActivation23R1, self).get_kpi(inter_release=inter_release)

        if use_restrictions:
            self.operation_details["Timeout"] += self.restrictions.use_restrictions_from_OM_GEN_SFS_PERF_CAP_13441()

        return self.operation_details
